The robust version is **Postgres triggers** on the audited tables (`accounts`, `orders`, `users`, `sessions`), backed by a generic trigger function:

```sql
create table audit_log (
  id           bigserial primary key,
  occurred_at  timestamptz not null default now(),
  tx_id        bigint not null default txid_current(),   -- groups multi-row writes from one transaction
  table_name   text not null,
  row_id       text not null,
  action       text not null check (action in ('INSERT','UPDATE','DELETE')),
  actor_id     uuid,          -- from session var, see below
  actor_email  text,
  before       jsonb,
  after        jsonb
);

create function audit_row() returns trigger as $$
begin
  insert into audit_log (table_name, row_id, action, actor_id, actor_email, before, after)
  values (
    TG_TABLE_NAME,
    coalesce(new.id, old.id)::text,
    TG_OP,
    nullif(current_setting('app.actor_id', true), '')::uuid,
    nullif(current_setting('app.actor_email', true), ''),
    case when TG_OP <> 'INSERT' then to_jsonb(old) end,
    case when TG_OP <> 'DELETE' then to_jsonb(new) end
  );
  return coalesce(new, old);
end;
$$ language plpgsql security definer;

create trigger trg_audit_accounts after insert or update or delete on accounts
  for each row execute function audit_row();
-- same for orders, users, sessions
```

This gets you "what changed" (full before/after row) and "when" for free, and it fires no matter what writes the row — the app, a migration, an admin doing a manual fix.

